lab.solution:
def should_accept(event_time, previous_time, gap=250):
    return previous_time is None or event_time - previous_time >= gap

accepted = []
last = None
for time_ms in [1000, 1100, 1300]:
    if should_accept(time_ms, last):
        accepted.append(time_ms)
        last = time_ms

assert accepted == [1000, 1300]
